# Risky pattern: each += may copy everything built so far
def shout_slow(words):
    result = ""
    for w in words:
        result += w.upper() + "!"
    return result

# Standard pattern: collect parts, join once, O(total length)
def shout(words):
    parts = []
    for w in words:
        parts.append(w.upper())
        parts.append("!")
    return "".join(parts)

# Editing characters: convert to a list, edit, join back
def capitalize_words(s):
    chars = list(s)
    for i in range(len(chars)):
        if i == 0 or chars[i - 1] == " ":
            chars[i] = chars[i].upper()
    return "".join(chars)

print(shout(["hi", "there"]))           # HI!THERE!
print(capitalize_words("hello world"))  # Hello World

def move_zeros(nums):
    write = 0                       # nums[:write] is the finished part
    for read in range(len(nums)):
        if nums[read] != 0:
            nums[write] = nums[read]
            write += 1
    for i in range(write, len(nums)):
        nums[i] = 0

def reverse(nums, lo, hi):
    """Reverse nums[lo..hi], both ends inclusive, in place."""
    while lo < hi:
        nums[lo], nums[hi] = nums[hi], nums[lo]
        lo += 1
        hi -= 1

nums = [0, 1, 0, 3, 12]
move_zeros(nums)
print(nums)                 # [1, 3, 12, 0, 0]

letters = list("abcdef")
reverse(letters, 1, 4)
print("".join(letters))     # aedcbf

